import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#define THREADS 256
#define SPLIT 64
__global__ void bn_stats_partial_kernel(
    const float* __restrict__ x,
    double* __restrict__ psum,
    double* __restrict__ psq,
    int N, int C, int H, int W
) {
    const int tid = threadIdx.x;
    const int c = blockIdx.x / SPLIT;
    const int r = blockIdx.x - c * SPLIT;
    const long long HW = 1LL * H * W;
    const bool vec4 = ((HW & 3LL) == 0LL);
    const int n_begin = (int)((1LL * N * r) / SPLIT);
    const int n_end = (int)((1LL * N * (r + 1)) / SPLIT);
    double sum0 = 0.0, sum1 = 0.0, sum2 = 0.0, sum3 = 0.0;
    double sq0 = 0.0, sq1 = 0.0, sq2 = 0.0, sq3 = 0.0;
    if (vec4) {
        const long long HW4 = HW >> 2;
        const long long chan4 = 1LL * C * HW4;
        const float4* cbase = reinterpret_cast<const float4*>(x) + 1LL * c * HW4;
        for (int n = n_begin; n < n_end; ++n) {
            const float4* base = cbase + 1LL * n * chan4;
            long long v = tid;
            for (; v + 3LL * THREADS < HW4; v += 4LL * THREADS) {
                const float4 va = __ldcs(base + v);
                const float4 vb = __ldcs(base + (v + THREADS));
                const float4 vc = __ldcs(base + (v + 2LL * THREADS));
                const float4 vd = __ldcs(base + (v + 3LL * THREADS));
                sum0 += (double)va.x + (double)va.y + (double)va.z + (double)va.w;
                sum1 += (double)vb.x + (double)vb.y + (double)vb.z + (double)vb.w;
                sum2 += (double)vc.x + (double)vc.y + (double)vc.z + (double)vc.w;
                sum3 += (double)vd.x + (double)vd.y + (double)vd.z + (double)vd.w;
                sq0 += (double)va.x * (double)va.x + (double)va.y * (double)va.y +
                       (double)va.z * (double)va.z + (double)va.w * (double)va.w;
                sq1 += (double)vb.x * (double)vb.x + (double)vb.y * (double)vb.y +
                       (double)vb.z * (double)vb.z + (double)vb.w * (double)vb.w;
                sq2 += (double)vc.x * (double)vc.x + (double)vc.y * (double)vc.y +
                       (double)vc.z * (double)vc.z + (double)vc.w * (double)vc.w;
                sq3 += (double)vd.x * (double)vd.x + (double)vd.y * (double)vd.y +
                       (double)vd.z * (double)vd.z + (double)vd.w * (double)vd.w;
            }
            for (; v < HW4; v += THREADS) {
            const float4 val = __ldcs(base + v);
                sum0 += (double)val.x + (double)val.y + (double)val.z + (double)val.w;
                sq0 += (double)val.x * (double)val.x +
                       (double)val.y * (double)val.y +
                       (double)val.z * (double)val.z +
                       (double)val.w * (double)val.w;
            }
        }
    } else {
        for (int n = n_begin; n < n_end; ++n) {
            const float* base = x + (1LL * n * C + c) * HW;
            long long s = tid;
            for (; s + 3LL * THREADS < HW; s += 4LL * THREADS) {
                const float va = __ldcs(base + s);
                const float vb = __ldcs(base + (s + THREADS));
                const float vc = __ldcs(base + (s + 2LL * THREADS));
                const float vd = __ldcs(base + (s + 3LL * THREADS));
                sum0 += (double)va; sum1 += (double)vb; sum2 += (double)vc; sum3 += (double)vd;
                sq0 += (double)va * (double)va; sq1 += (double)vb * (double)vb;
                sq2 += (double)vc * (double)vc; sq3 += (double)vd * (double)vd;
            }
            for (; s < HW; s += THREADS) {
            const float v = __ldcs(base + s);
                sum0 += (double)v;
                sq0 += (double)v * (double)v;
            }
        }
    }
    __shared__ double ssum[THREADS / 32];
    __shared__ double ssumsq[THREADS / 32];
    const double local_sum = (sum0 + sum1) + (sum2 + sum3);
    const double local_sumsq = (sq0 + sq1) + (sq2 + sq3);
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const unsigned int full_mask = 0xffffffffu;
    double warp_sum = local_sum;
    double warp_sumsq = local_sumsq;
    for (int offset = 16; offset > 0; offset >>= 1) {
        warp_sum += __shfl_down_sync(full_mask, warp_sum, offset);
        warp_sumsq += __shfl_down_sync(full_mask, warp_sumsq, offset);
    }
    if (lane == 0) {
        ssum[warp] = warp_sum;
        ssumsq[warp] = warp_sumsq;
    }
    __syncthreads();
    if (warp == 0) {
        double block_sum = (lane < THREADS / 32) ? ssum[lane] : 0.0;
        double block_sumsq = (lane < THREADS / 32) ? ssumsq[lane] : 0.0;
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum += __shfl_down_sync(full_mask, block_sum, offset);
            block_sumsq += __shfl_down_sync(full_mask, block_sumsq, offset);
        }
        if (lane == 0) {
            const int slot = c * SPLIT + r;
            psum[slot] = block_sum;
            psq[slot] = block_sumsq;
        }
    }
}
__global__ void bn_finalize_kernel(
    const double* __restrict__ psum,
    const double* __restrict__ psq,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    float* __restrict__ batch_mean,
    float* __restrict__ batch_inv_std,
    long long total,
    float momentum,
    float eps
) {
    const int c = blockIdx.x;
    if (threadIdx.x == 0) {
        double sum = 0.0;
        double sumsq = 0.0;
        const int base = c * SPLIT;
        for (int r = 0; r < SPLIT; ++r) {
            sum += psum[base + r];
            sumsq += psq[base + r];
        }
        const double n = (double)total;
        const double mean = sum / n;
        double var = sumsq / n - mean * mean;
        if (var < 0.0) var = 0.0;
        batch_mean[c] = (float)mean;
        batch_inv_std[c] = rsqrtf((float)var + eps);
        running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * (float)mean;
        if (total > 1) {
            const double unbiased = var * n / (n - 1.0);
            running_var[c] = (1.0f - momentum) * running_var[c] + momentum * (float)unbiased;
        }
    }
}
__global__ void bn_norm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    const double* __restrict__ psum,
    const double* __restrict__ psq,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int N, int C, int H, int W,
    bool training,
    float momentum,
    float eps
) {
    const int tid = threadIdx.x;
    const int c = blockIdx.x / SPLIT;
    const int r = blockIdx.x - c * SPLIT;
    const long long HW = 1LL * H * W;
    const bool vec4 = ((HW & 3LL) == 0LL);
    const int n_begin = (int)((1LL * N * r) / SPLIT);
    const int n_end = (int)((1LL * N * (r + 1)) / SPLIT);
    float mean, inv_std;
    if (training) {
        double lsum = 0.0, lsq = 0.0;
        const int pbase = c * SPLIT;
        for (int i = tid; i < SPLIT; i += THREADS) {
            lsum += psum[pbase + i];
            lsq += psq[pbase + i];
        }
        const int lane = tid & 31;
        const int warp = tid >> 5;
        const unsigned int full_mask = 0xffffffffu;
        for (int offset = 16; offset > 0; offset >>= 1) {
            lsum += __shfl_down_sync(full_mask, lsum, offset);
            lsq += __shfl_down_sync(full_mask, lsq, offset);
        }
        __shared__ double red_sum[THREADS / 32];
        __shared__ double red_sq[THREADS / 32];
        __shared__ double s_mean;
        __shared__ double s_inv;
        if (lane == 0) {
            red_sum[warp] = lsum;
            red_sq[warp] = lsq;
        }
        __syncthreads();
        if (warp == 0) {
            double bsum = (lane < THREADS / 32) ? red_sum[lane] : 0.0;
            double bsq = (lane < THREADS / 32) ? red_sq[lane] : 0.0;
            for (int offset = 16; offset > 0; offset >>= 1) {
                bsum += __shfl_down_sync(full_mask, bsum, offset);
                bsq += __shfl_down_sync(full_mask, bsq, offset);
            }
            if (lane == 0) {
                const double n = (double)(1LL * N * HW);
                const double m = bsum / n;
                double var = bsq / n - m * m;
                if (var < 0.0) var = 0.0;
                s_mean = m;
                s_inv = rsqrtf((float)var + eps);
                if (r == 0) {
                    running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * (float)m;
                    if (n > 1.0) {
                        const double unbiased = var * n / (n - 1.0);
                        running_var[c] = (1.0f - momentum) * running_var[c] + momentum * (float)unbiased;
                    }
                }
            }
        }
        __syncthreads();
        mean = (float)s_mean;
        inv_std = (float)s_inv;
    } else {
        mean = running_mean[c];
        inv_std = rsqrtf(running_var[c] + eps);
    }
    const float scale = gamma[c] * inv_std;
    const float shift = beta[c] - mean * scale;
    if (vec4) {
        const long long HW4 = HW >> 2;
        const long long chan4 = 1LL * C * HW4;
        const float4* in_c = reinterpret_cast<const float4*>(x) + 1LL * c * HW4;
        float4* out_c = reinterpret_cast<float4*>(y) + 1LL * c * HW4;
        for (int n = n_begin; n < n_end; ++n) {
            const float4* in_base = in_c + 1LL * n * chan4;
            float4* out_base = out_c + 1LL * n * chan4;
            long long v = tid;
            for (; v + 3LL * THREADS < HW4; v += 4LL * THREADS) {
                const float4 va = __ldcs(in_base + v);
                const float4 vb = __ldcs(in_base + (v + THREADS));
                const float4 vc = __ldcs(in_base + (v + 2LL * THREADS));
                const float4 vd = __ldcs(in_base + (v + 3LL * THREADS));
                float4 oa, ob, oc, od;
                oa.x = va.x * scale + shift;
                oa.y = va.y * scale + shift;
                oa.z = va.z * scale + shift;
                oa.w = va.w * scale + shift;
                ob.x = vb.x * scale + shift;
                ob.y = vb.y * scale + shift;
                ob.z = vb.z * scale + shift;
                ob.w = vb.w * scale + shift;
                oc.x = vc.x * scale + shift;
                oc.y = vc.y * scale + shift;
                oc.z = vc.z * scale + shift;
                oc.w = vc.w * scale + shift;
                od.x = vd.x * scale + shift;
                od.y = vd.y * scale + shift;
                od.z = vd.z * scale + shift;
                od.w = vd.w * scale + shift;
                __stcs(out_base + v, oa);
                __stcs(out_base + (v + THREADS), ob);
                __stcs(out_base + (v + 2LL * THREADS), oc);
                __stcs(out_base + (v + 3LL * THREADS), od);
            }
            for (; v < HW4; v += THREADS) {
                const float4 val = __ldcs(in_base + v);
                float4 out;
                out.x = val.x * scale + shift;
                out.y = val.y * scale + shift;
                out.z = val.z * scale + shift;
                out.w = val.w * scale + shift;
                __stcs(out_base + v, out);
            }
        }
    } else {
        for (int n = n_begin; n < n_end; ++n) {
            const long long off = (1LL * n * C + c) * HW;
            const float* in_base = x + off;
            float* out_base = y + off;
            long long s = tid;
            for (; s + 3LL * THREADS < HW; s += 4LL * THREADS) {
                const float va = __ldcs(in_base + s);
                const float vb = __ldcs(in_base + (s + THREADS));
                const float vc = __ldcs(in_base + (s + 2LL * THREADS));
                const float vd = __ldcs(in_base + (s + 3LL * THREADS));
                __stcs(out_base + s, va * scale + shift);
                __stcs(out_base + (s + THREADS), vb * scale + shift);
                __stcs(out_base + (s + 2LL * THREADS), vc * scale + shift);
                __stcs(out_base + (s + 3LL * THREADS), vd * scale + shift);
            }
            for (; s < HW; s += THREADS) {
                __stcs(out_base + s, __ldcs(in_base + s) * scale + shift);
            }
        }
    }
}
torch::Tensor bn_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    auto xc = x.contiguous();
    auto g = gamma.contiguous();
    auto b = beta.contiguous();
    auto rm = running_mean.contiguous();
    auto rv = running_var.contiguous();
    auto y = at::empty_like(xc);
    const int N = (int)xc.size(0);
    const int C = (int)xc.size(1);
    const int H = (int)xc.size(2);
    const int W = (int)xc.size(3);
    const long long total = 1LL * N * H * W;
    dim3 grid(C * SPLIT);
    dim3 block(THREADS);
    auto stream = at::cuda::getCurrentCUDAStream();
    if (training) {
        auto dopts = xc.options().dtype(at::kDouble);
        auto psum = at::empty({C, SPLIT}, dopts);
        auto psq = at::empty({C, SPLIT}, dopts);
        bn_stats_partial_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(),
            psum.data_ptr<double>(),
            psq.data_ptr<double>(),
            N, C, H, W
        );
        bn_norm_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(),
            y.data_ptr<float>(),
            g.data_ptr<float>(),
            b.data_ptr<float>(),
            psum.data_ptr<double>(),
            psq.data_ptr<double>(),
            rm.data_ptr<float>(),
            rv.data_ptr<float>(),
            N, C, H, W,
            true,
            (float)momentum,
            (float)eps
        );
    } else {
        bn_norm_kernel<<<grid, block, 0, stream>>>(
            xc.data_ptr<float>(),
            y.data_ptr<float>(),
            g.data_ptr<float>(),
            b.data_ptr<float>(),
            nullptr,
            nullptr,
            rm.data_ptr<float>(),
            rv.data_ptr<float>(),
            N, C, H, W,
            false,
            (float)momentum,
            (float)eps
        );
    }
    return y;
}
